    /** @return array{rated: int, unrated: list<array{provider: string, request_id: string, ts: \DateTimeImmutable}>} */
    public function rate(): array
    {
        return $this->db->transactional(function (): array {
            $unratedEvents = $this->db->fetchAllAssociative(
                "SELECT id, provider, provider_request_id, model, ts, tokens_input, tokens_output, tokens_cache_read, tokens_cache_write
                 FROM usage_events WHERE status = 'unrated' ORDER BY provider, model, ts");
            if ($unratedEvents === []) return ['rated' => 0, 'unrated' => []];

            // group by provider/model
            $offPeaks = [...load providers...];
            $priceCache = []; // "provider|model" => list of price rows

            $rated = 0; $unrated = [];
            $stmt prepared = $this->db->prepare('UPDATE usage_events SET status=:s, price_row_id=:pid, cost=:cost WHERE id=:id');
            foreach ($unratedEvents as $row) {
                $key = $row['provider'].'|'.$row['model'];
                $rows = $priceCache[$key] ??= $this->loadPriceRows($row['provider'], $row['model']);
                $best = null;
                foreach ($rows as $prow) { if ($prow['valid_from'] <= ts) $best = $prow; else break; } // ascending sort
                if ($best === null) { $unrated[] = [...]; continue; }
                $entry = new PriceEntry($best['unit'], [input=>..., ...]);
                $cost = $this->rater->rate(new UsageRecord(...), $entry, $offPeaks[$row['provider']] ?? null);
                $stmt->execute([...]); ++$rated;
            }
            return ['rated' => $rated, 'unrated' => $unrated];
        });
    }
}
```

